  test("AC-1 Signed-in customer proceeds through checkout to payment without re-authentication", async ({ page }) => {
    // Sign in
    await page.goto("/auth/login");
    await page.getByLabel("Email address *").fill(process.env["AQA_APP_USER"] ?? "");
    await page.getByLabel("Password *").fill(process.env["AQA_APP_PASS"] ?? "");
    await page.getByRole("button", { name: "Login" }).click();

    // Precondition: assert login succeeded before proceeding
    await expect(page.getByTestId("nav-menu")).toBeVisible({ timeout: 10000 });

    // Add product to cart
    await page.goto("/");
    await page.getByTestId("product-01JCQX5DKWNKAQN7YXVZ6XFBC").click();
    await page.getByTestId("add-to-cart").click();
    await expect(page.getByText("Product added to shopping cart.").first()).toBeVisible();

    // Proceed to checkout
    await page.goto("/cart");
    await page.getByTestId("proceed-1").click();

    // Assert: we are on checkout and NOT shown a login prompt
    await expect(page).toHaveURL(/\/checkout/);
    await expect(page.getByRole("heading", { name: "Login" })).not.toBeVisible();
  });

